  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the booking price after applying membership discount rules.
   * Algorithm:
   * 1. If customer is null or bookingTime is null, return price.
   * 2. If customer.membershipPackage is null, return price.
   * 3. If membershipPackage does not contain Award.DISCOUNTS, return price.
   * 4. Check whether bookingTime is at least 24 hours before this trip's departure time.
   * 5. If not at least 24 hours before departure, return price.
   * 6. Compute discountedPrice = price * 0.8.
   * 7. Round the result to one decimal place.
   * 8. Return the rounded discountedPrice.
   * Related Features:
   * - price
   * - departureTime
   * - driver
   * - bookings
   * - Trip.calculateMonthlyPoints(Customer, String)
   * - MembershipPackage.hasAward(Award)
   * Related Classes: Trip, Customer, MembershipPackage, Award
   * Input:
   * - customer: the customer for which discount eligibility is evaluated.
   * - bookingTime: the booking date/time as a String; must be comparable with departureTime.
   * Output:
   * - double:
   *   - original price if inputs are invalid or the reward condition is unmet.
   *   - otherwise price after a 20% discount, rounded to one decimal place.
   * Pre-condition:
   * - Trip exists and price is defined.
   * - departureTime and bookingTime must be in a comparable time format.
   * Post-condition:
   * - No state is modified.
   * - Returned amount preserves one decimal place when discounted.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null)
    {
      return price;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.DISCOUNTS))
    {
      return price;
    }
    if (departureTime == null)
    {
      return price;
    }
    try
    {
      long bookingMillis = Long.parseLong(bookingTime.trim());
      long departureMillis = Long.parseLong(departureTime.trim());
      long diff = departureMillis - bookingMillis;
      if (diff < 24L * 60L * 60L * 1000L)
      {
        return price;
      }
      double discountedPrice = price * 0.8d;
      return Math.round(discountedPrice * 10.0d) / 10.0d;
    }
    catch (Exception e)
    {
      return price;
    }
    
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate reward points contributed by this trip for a customer in a given month.
   * Algorithm:
   * 1. If customer is null or currentMonth is null/empty, return 0.
   * 2. If customer.membershipPackage is null, return 0.
   * 3. If membershipPackage does not contain Award.POINTS, return 0.
   * 4. Initialize points = 0.
   * 5. For each booking in bookings:
   *    - If booking.customer equals the given customer and booking.isInMonth(currentMonth) is true,
   *      add booking.numberOfSeats * 5 to points.
   * 6. Return points.
   * Related Features:
   * - price
   * - bookings
   * - Trip.bookings
   * - Trip.getBookedSeats()
   * - Booking.isInMonth(String)
   * - MembershipPackage.hasAward(Award)
   * Related Classes: Trip, Booking, Customer, MembershipPackage, Award
   * Input:
   * - customer: customer whose points are computed.
   * - currentMonth: month identifier used for filtering bookings.
   * Output:
   * - int:
   *   - total points earned from this trip for the customer in the month.
   *   - 0 for invalid input or ineligible rewards.
   * Pre-condition:
   * - Trip and customer exist.
   * - Customer must be eligible for POINTS rewards to earn points.
   * Post-condition:
   * - No state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null || currentMonth.isEmpty())
    {
      return 0;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.POINTS))
    {
      return 0;
    }
    int points = 0;
    if (bookings != null)
    {
      for (Booking booking : bookings)
      {
        if (booking != null && customer.equals(booking.getCustomer()) && booking.isInMonth(currentMonth))
        {
          points += booking.getNumberOfSeats() * 5;
        }
      }
    }
    return points;
    
  }

